arguments.command:
WC="/Users/billtse/Desktop/泓家系统/恒林网关"
echo "=== 工作副本 config 顶层字段（借 workbuddy node 实读） ==="
NB="$HOME/.workbuddy/binaries/node/versions/22.22.2-6/bin/node"
"$NB" -e "
const c=JSON.parse(require('fs').readFileSync('$WC/gateway.config.json','utf8'));
console.log('顶层 keys:', Object.keys(c).join(', '));
console.log('shadowMode =', c.shadowMode);
console.log('sharedCircuitBreaker =', c.sharedCircuitBreaker);
console.log('routingWeights =', JSON.stringify(c.routingWeights||null));
"
echo
echo "=== 若缺 sharedCircuitBreaker，看原文里怎么写的 ==="
grep -n 'sharedCircuitBreaker\|shadowMode\|routingWeights' "$WC/gateway.config.json" || echo "(grep 无命中)"

