141:const SHARED_CB_EFF = GW_CONFIG.sharedCircuitBreaker;          // P2.4：完整 failureDomain 共享熔断（默认关，需实跑观察同域同生共死后手动开）
255:  failureDomains: {},      // P1.3：同域分组 host→[legId]（从 baseURL 派生，Agnes 两腿同域 api.agnes-ai.cn）
