      // P2.4：完整 failureDomain 共享熔断（默认关=只本腿熔断；开=同域任腿 3 败熔断→同域兄弟腿也进 60s 半熔断。
      // 默认关因风险高（Agnes 一号单 key 挂≠整域挂，误开会把二号也熔断→两腿全灭只剩 openrouter 跨域腿），需实跑观察「同域确实同生共死」后手动开）
      sharedCircuitBreaker: doc.sharedCircuitBreaker === true,
      source: 'gateway.config.json',
    };
  } catch (e) {
    console.warn(`[警告] 配置文件不可用(${e.message})，退回代码内默认名册`);
--- L130 ---
      shadowMode: true, // P2.2：fallback 也默认影子态（零风险）
      routingWeights: { lat: .35, hlth: .20, cost: .15, load: .15, size: .10, prio: .05 },
      sharedCircuitBreaker: false, // P2.4：fallback 默认关（共享熔断风险高，需实跑观察后手动开）
      source: 'builtin-fallback',
    };
  }
}
--- L141 ---
const SHADOW_MODE_EFF = GW_CONFIG.shadowMode;                 // P2.2
const ROUTING_WEIGHTS_EFF = GW_CONFIG.routingWeights;          // P2.2
const SHARED_CB_EFF = GW_CONFIG.sharedCircuitBreaker;          // P2.4：完整 failureDomain 共享熔断（默认关，需实跑观察同域同生共死后手动开）

const LOG_DIR = path.join(process.env.HOME, 'Desktop', '泓家系统', 'DSH 平时任务', '恒林网关', 'logs');
const JSONL_PATH = path.join(LOG_DIR, 'requests.jsonl');

