{"command":"WC="/Users/billtse/Desktop/泓家系统/恒林网关"
echo "=== 完整 config（带行号，看清全结构） ==="
cat -n "$WC/gateway.config.json"
echo
echo "=== 大括号配平（{ = } 才合法） ==="
NB="$HOME/.workbuddy/binaries/node/versions/22.22.2-6/bin/node"
"$NB" -e "
const s=require('fs').readFileSync('$WC/gateway.config.json','utf8');
console.log('count { =', [...s].filter(c=>c==='{').length, ' count } =', [...s].filter(c=>c==='}').length);
""}

{"command":"WC="/Users/billtse/Desktop/泓家系统/恒林网关"
NB="$HOME/.workbuddy/binaries/node/versions/22.22.2-6/bin/node"
echo "=== config 补字段后复核（JSON 合法 + 顶层键 + 两个 P2 开关值） ==="
"$NB" -e "
const c=JSON.parse(require('fs').readFileSync('$WC/gateway.config.json','utf8'));
console.log('JSON 合法 ✓  顶层键:', Object.keys(c).join(', '));
console.log('shadowMode =', c.shadowMode, '  sharedCircuitBreaker =', c.sharedCircuitBreaker);
"
echo
echo "=== gateway.js 再 --check（应仍 1117 行，未受 config 改动影响） ==="
wc -l "$WC/gateway.js"
"$NB" --check "$WC/gateway.js" && echo "gateway.js --check OK""}

{"command":"WC="/Users/billtse/Desktop/泓家系统/恒林网关"
echo "=== 工作副本 config 顶层字段（借 workbuddy node 实读） ==="
NB="$HOME/.workbuddy/binaries/node/versions/22.22.2-6/bin/node"
"$NB" -e "
const c=JSON.parse(require('fs').readFileSync('$WC/gateway.config.json','utf8'));
console.log('顶层 keys:', Object.keys(c).join(', '));
console.log('shadowMode =', c.shadowMode);
console.log('sharedCircuitBreaker =', c.sharedCircuitBreaker);
console.log('routingWeights =', JSON.stringify(c.routingWeights||null));
"
echo
echo "=== 若缺 sharedCircuitBreaker，看原文里怎么写的 ==="
grep -n 'sharedCircuitBreaker\|shadowMode\|routingWeights' "$WC/gateway.config.json" || echo "(grep 无命中)""}

